`timescale 1ns/1ps
module tb_l5_q128_silu_product;
 localparam N=1146880;logic clk;/* verilator lint_off SYNCASYNCNET */logic rst_n;/* verilator lint_on SYNCASYNCNET */logic iv,ir,ov,orr;logic[31:0]x,y;logic[4:0]f,fo;logic[31:0]ac,cc;logic[511:0]va,vb,vo;logic[4:0]vf,vfo;logic[31:0]g[0:N-1],u[0:N-1],es[0:N-1],ep[0:N-1];integer cycles,sc,pc;logic[63:0]hs,hp;
 always #5 clk=~clk;always@(posedge clk)if(!rst_n)cycles<=0;else cycles<=cycles+1;
 fp32_silu silu(.clk_i(clk),.rst_ni(rst_n),.in_valid_i(iv),.in_ready_o(ir),.x_i(x),.out_valid_o(ov),.out_ready_i(orr),.y_o(y),.exception_flags_o(f),.accepted_o(ac),.completed_o(cc));fp32_vector_alu#(.LANES(16))mul16(.op_i(1'b1),.a_i(va),.b_i(vb),.out_o(vo),.exception_flags_o(vf));
 initial begin integer st;clk=0;rst_n=0;iv=0;orr=1;fo=0;vfo=0;hs=64'hcbf29ce484222325;hp=hs;$readmemh("work/results/l5_q128_silu_product/vectors/gate.memh",g);$readmemh("work/results/l5_q128_silu_product/vectors/up.memh",u);$readmemh("work/results/l5_q128_silu_product/vectors/silu.memh",es);$readmemh("work/results/l5_q128_silu_product/vectors/product.memh",ep);repeat(3)@(posedge clk);rst_n=1;st=cycles;for(int i=0;i<N;i++)begin @(negedge clk);x=g[i];iv=1;do@(posedge clk);while(!ir);@(negedge clk);iv=0;do@(posedge clk);while(!(ov&&orr));@(negedge clk);if(y!==es[i])$fatal(1,"q128 silu i=%0d",i);g[i]=y;fo|=f;hs=(hs^{32'd0,y})*64'h100000001b3;end sc=cycles-st;st=cycles;for(int c=0;c<71680;c++)begin @(negedge clk);for(int i=0;i<16;i++)begin va[i*32+:32]=g[c*16+i];vb[i*32+:32]=u[c*16+i];end #1;if(vo!=={ep[c*16+15],ep[c*16+14],ep[c*16+13],ep[c*16+12],ep[c*16+11],ep[c*16+10],ep[c*16+9],ep[c*16+8],ep[c*16+7],ep[c*16+6],ep[c*16+5],ep[c*16+4],ep[c*16+3],ep[c*16+2],ep[c*16+1],ep[c*16]})$fatal(1,"q128 product c=%0d",c);vfo|=vf;for(int i=0;i<16;i++)hp=(hp^{32'd0,vo[i*32+:32]})*64'h100000001b3;end pc=cycles-st;if(ac!=N||cc!=N||fo[4:1]!=0||vfo[4:1]!=0)$fatal(1,"q128 silu accounting");$display("L5_Q128_SILU_PRODUCT_PASS lanes=1146880 product_chunks=71680 total_cycles=%0d silu_cycles=%0d product_cycles=%0d silu_fnv64=%016h product_fnv64=%016h",cycles,sc,pc,hs,hp);$finish;end
 initial begin repeat(11000000)@(posedge clk);$fatal(1,"q128 silu timeout");end
endmodule
